// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { noise2D } from "@remotion/noise";
import { makeLoadFont } from '../googleFonts';
const loadArchivoBlack = makeLoadFont('ArchivoBlack');

// Load font at module level
const { fontFamily: archivoBlackFamily } = loadArchivoBlack();

// Define Schema


export type DeadSalesDashboardProps = Record<string, any>;

const DeadSalesDashboard: React.FC<DeadSalesDashboardProps> = ({
  backgroundColor = "#030405",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#6DE6DC",
  primaryText = "$0",
  secondaryText = "no sales.",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; // responsive scale factor

  // Safety logic for transparent background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Custom easing matching the prompt's request: cubic-bezier(.2,.9,.3,1.2)
  const slideEase = Easing.bezier(0.2, 0.9, 0.3, 1.2);

  // --- Animation Drivers ---

  // 1. Slow Sinking Motion of the entire HUD
  const sinkY = interpolate(frame, [0, durationInSeconds * 30], [0, 80 * s]);

  // 2. Flickering text "$0"
  const textFlickerRaw = noise2D("text-flicker", frame / 4, 0);
  const textOpacity = interpolate(textFlickerRaw, [-1, 1], [0.6, 1]);

  // 3. Graph Line Drawing (flat line)
  const graphDrawStart = 30;
  const graphDrawEnd = 90;
  const graphWidth = 560 * s;
  const currentGraphLength = interpolate(
    frame,
    [graphDrawStart, graphDrawEnd],
    [0, graphWidth],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) }
  );

  // 4. Graph Line & Head Sputtering (Noise)
  const lineFlickerRaw = noise2D("line-flicker", frame / 2, 0);
  const lineOpacity = interpolate(lineFlickerRaw, [-1, 1], [0.3, 0.8]);
  const headFlickerRaw = noise2D("head-flicker", frame, 0);
  const headOpacity = interpolate(headFlickerRaw, [-1, 1], [0.4, 1]);
  // The sputtering head occasionally drops down slightly to look "weak"
  const headSputterY = interpolate(noise2D("head-y", frame, 0), [-1, 1], [-2 * s, 4 * s]);

  // 5. "no sales." text fade in
  const noSalesOpacity = interpolate(frame, [100, 130], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // 6. Notification Rail Chip Sequence
  const chipSlideInStart = 110;
  const chipSlideInEnd = 140;
  const chipSlideOutStart = 220; // Will happen late in the composition
  const chipSlideOutEnd = 250;

  let chipTranslateX = 150 * s; // Starts fully off to the right of its rail
  if (frame >= chipSlideInStart && frame < chipSlideOutStart) {
    chipTranslateX = interpolate(
      frame,
      [chipSlideInStart, chipSlideInEnd],
      [150 * s, 0],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: slideEase }
    );
  } else if (frame >= chipSlideOutStart) {
    chipTranslateX = interpolate(
      frame,
      [chipSlideOutStart, chipSlideOutEnd],
      [0, 150 * s],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.quad) }
    );
  }

  // 7. Chip Dot Blink
  const blinkFrameStart = 160;
  let dotOpacity = 0.1;
  if (frame >= blinkFrameStart && frame < blinkFrameStart + 4) {
    dotOpacity = 1;
  } else if (frame >= blinkFrameStart + 4 && frame < blinkFrameStart + 8) {
    dotOpacity = 0.5;
  } else if (frame >= blinkFrameStart + 8) {
    dotOpacity = 0.1;
  }

  // --- Generative Data ---

  // Dust particles (stable generation using useMemo and indices)
  const particles = useMemo(() => {
    return Array.from({ length: 60 }).map((_, i) => {
      // Deterministic pseudo-random values based on index
      const seedX = i * 1.1;
      const seedY = i * 2.3;
      const seedZ = i * 3.7;
      const size = (1 + (i % 3)) * 1.5 * s;
      const baseOpacity = 0.1 + (i % 5) * 0.05;
      const driftSpeed = 0.002 + (i % 3) * 0.001;
      return { seedX, seedY, seedZ, size, baseOpacity, driftSpeed };
    });
  }, [s]);

  // Grid lines for the graph (stable array)
  const gridCols = 6;
  const gridRows = 4;
  const graphHeight = 220 * s;

  // --- Styling Helpers ---

  // Refractive Glass style base
  const glassPanelStyle: React.CSSProperties = {
    background: "rgba(15, 20, 25, 0.4)",
    backdropFilter: `blur(${16 * s}px) brightness(0.8)`,
    WebkitBackdropFilter: `blur(${16 * s}px) brightness(0.8)`,
    borderRadius: `${32 * s}px`,
    border: `${1 * s}px solid rgba(255, 255, 255, 0.08)`,
    boxShadow: `
      inset 0 0 ${40 * s}px rgba(255, 255, 255, 0.03),
      ${-3 * s}px 0 ${6 * s}px rgba(109, 230, 220, 0.08), 
      ${3 * s}px 0 ${6 * s}px rgba(255, 50, 50, 0.06), 
      0 ${30 * s}px ${60 * s}px rgba(0, 0, 0, 0.6)
    `,
    position: "relative",
    overflow: "hidden", // for inner light/reflections
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* 3D Scene Perspective Container */}
      <div
        style={{
          width: "100%",
          height: "100%",
          perspective: `${2000 * s}px`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transformStyle: "preserve-3d",
        }}
      >
        
        {/* Environment / Drifting Dust Particles */}
        <div style={{ position: "absolute", width: "100%", height: "100%", transformStyle: "preserve-3d" }}>
          {particles.map((p, i) => {
            // Calculate drifting positions using noise
            const posX = interpolate(noise2D(`px-${i}`, frame * p.driftSpeed, p.seedX), [-1, 1], [-width * 0.5, width * 1.5]);
            const posY = interpolate(noise2D(`py-${i}`, frame * p.driftSpeed, p.seedY), [-1, 1], [-height * 0.5, height * 1.5]);
            const posZ = interpolate(noise2D(`pz-${i}`, 0, p.seedZ), [-1, 1], [-800 * s, 800 * s]);
            
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: posX,
                  top: posY,
                  width: p.size,
                  height: p.size,
                  backgroundColor: "#ffffff",
                  borderRadius: "50%",
                  opacity: p.baseOpacity,
                  transform: `translateZ(${posZ}px)`,
                  boxShadow: `0 0 ${p.size * 2}px rgba(255,255,255,0.8)`,
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* The entire HUD Assembly */}
        <div
          style={{
            position: "relative",
            transformStyle: "preserve-3d",
            // Tilted in 3D and sinking slowly
            transform: `rotateY(-14deg) rotateX(8deg) rotateZ(-2deg) translateY(${sinkY}px)`,
            display: "flex",
            alignItems: "center",
            transition: "none",
          }}
        >
          
          {/* Main Dashboard Panel */}
          <div
            style={{
              ...glassPanelStyle,
              width: `${720 * s}px`,
              height: `${800 * s}px`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              paddingTop: `${100 * s}px`,
            }}
          >
            {/* Inner Refractive Layer (fakes thickness) */}
            <div
              style={{
                position: "absolute",
                inset: `${4 * s}px`,
                borderRadius: `${28 * s}px`,
                border: `${1 * s}px solid rgba(255, 255, 255, 0.03)`,
                pointerEvents: "none",
              }}
            />

            {/* Top Section: $0 and No Sales */}
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", zIndex: 10 }}>
              <div
                style={{
                  fontFamily: archivoBlackFamily,
                  fontSize: `${120 * s}px`,
                  color: "#ffffff",
                  opacity: textOpacity,
                  textTransform: "lowercase",
                  lineHeight: 1,
                  textShadow: `0 0 ${20 * s}px rgba(255,255,255,0.4)`,
                  transition: "none",
                }}
              >
                {primaryText}
              </div>
              <div
                style={{
                  fontFamily: archivoBlackFamily,
                  fontSize: `${40 * s}px`,
                  color: "#666666", // Grey
                  opacity: noSalesOpacity,
                  textTransform: "lowercase",
                  marginTop: `${20 * s}px`,
                  letterSpacing: `${-1 * s}px`,
                  transition: "none",
                }}
              >
                {secondaryText}
              </div>
            </div>

            {/* Bottom Section: Graph Box */}
            <div
              style={{
                marginTop: `${80 * s}px`,
                width: graphWidth,
                height: graphHeight,
                border: `${1 * s}px solid rgba(255, 255, 255, 0.08)`,
                borderRadius: `${16 * s}px`,
                position: "relative",
                background: "rgba(0, 0, 0, 0.2)",
                boxShadow: `inset 0 0 ${30 * s}px rgba(0,0,0,0.5)`,
                overflow: "hidden",
              }}
            >
              {/* Grid Lines */}
              <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.2 }}>
                {Array.from({ length: gridCols - 1 }).map((_, i) => (
                  <line
                    key={`v-${i}`}
                    x1={(graphWidth / gridCols) * (i + 1)}
                    y1={0}
                    x2={(graphWidth / gridCols) * (i + 1)}
                    y2={graphHeight}
                    stroke="#ffffff"
                    strokeWidth={1 * s}
                    strokeDasharray={`${4 * s}, ${4 * s}`}
                  />
                ))}
                {Array.from({ length: gridRows - 1 }).map((_, i) => (
                  <line
                    key={`h-${i}`}
                    x1={0}
                    y1={(graphHeight / gridRows) * (i + 1)}
                    x2={graphWidth}
                    y2={(graphHeight / gridRows) * (i + 1)}
                    stroke="#ffffff"
                    strokeWidth={1 * s}
                    strokeDasharray={`${4 * s}, ${4 * s}`}
                  />
                ))}
              </svg>

              {/* The Weak Sputtering Graph Line */}
              {/* Positioned dead center vertically */}
              <svg
                width={graphWidth}
                height={graphHeight}
                style={{ position: "absolute", inset: 0, overflow: "visible" }}
              >
                {/* Reveal line by setting x2 to the interpolated length */}
                <line
                  x1={0}
                  y1={graphHeight / 2}
                  x2={currentGraphLength}
                  y2={graphHeight / 2}
                  stroke={accentColor}
                  strokeWidth={3 * s}
                  opacity={frame >= graphDrawStart ? lineOpacity : 0}
                  style={{ transition: "none" }}
                  strokeLinecap="round"
                />
                
                {/* Tip Rider: The sputtering head */}
                {/* Placed exactly at currentGraphLength, ensuring it never detaches */}
                <g
                  transform={`translate(${currentGraphLength}, ${graphHeight / 2 + headSputterY})`}
                  opacity={frame >= graphDrawStart ? headOpacity : 0}
                  style={{ transition: "none" }}
                >
                  {/* Core dot */}
                  <circle cx={0} cy={0} r={5 * s} fill="#ffffff" />
                  {/* Outer glow */}
                  <circle cx={0} cy={0} r={12 * s} fill={accentColor} opacity={0.6} filter={`blur(${4 * s}px)`} />
                  <circle cx={0} cy={0} r={24 * s} fill={accentColor} opacity={0.3} filter={`blur(${8 * s}px)`} />
                </g>
              </svg>
            </div>
          </div>

          {/* Side Notification Rail */}
          <div
            style={{
              ...glassPanelStyle,
              position: "absolute",
              right: `${-110 * s}px`,
              top: `${150 * s}px`,
              width: `${80 * s}px`,
              height: `${500 * s}px`,
              borderRadius: `${40 * s}px`,
              boxShadow: `
                inset 0 0 ${20 * s}px rgba(255, 255, 255, 0.03),
                0 ${20 * s}px ${40 * s}px rgba(0, 0, 0, 0.5)
              `,
              overflow: "hidden", // Hides the chip when it slides out
            }}
          >
            
            {/* The sliding notification chip */}
            <div
              style={{
                position: "absolute",
                top: `${40 * s}px`,
                left: `${10 * s}px`,
                width: `${60 * s}px`,
                height: `${120 * s}px`,
                background: "rgba(30, 40, 50, 0.6)",
                borderRadius: `${30 * s}px`,
                border: `${1 * s}px solid rgba(255, 255, 255, 0.1)`,
                boxShadow: `inset 0 0 ${10 * s}px rgba(255, 255, 255, 0.1)`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                transform: `translateX(${chipTranslateX}px)`,
                transition: "none",
              }}
            >
              {/* Teal Dot */}
              <div
                style={{
                  width: `${16 * s}px`,
                  height: `${16 * s}px`,
                  backgroundColor: accentColor,
                  borderRadius: "50%",
                  opacity: dotOpacity,
                  boxShadow: dotOpacity > 0.5 ? `0 0 ${15 * s}px ${accentColor}` : "none",
                  transition: "none",
                }}
              />
            </div>
            
          </div>
          
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DeadSalesDashboard;